1	/**
2	 * gh.ts — thin wrappers around the `gh` CLI and `git`. The one canonical
3	 * copy shared by every script and MCP server in this repo (workflow-invoked
4	 * `src/entrypoints/machinery/**` and Atomaton-tool-invoked `src/entrypoints/tools/**`
5	 * alike) -- see build-dist.ts for how this stays true in the deployed
6	 * output despite living in one shared place at dev time.
7	 */
8	
9	export interface RunResult {
10	  code: number;
11	  stdout: string;
12	  stderr: string;
13	}
14	
15	function run(cmd: string[]): RunResult {
16	  const proc = Bun.spawnSync({
17	    cmd,
18	    stdout: "pipe",
19	    stderr: "pipe",
20	  });
21	  return {
22	    code: proc.exitCode ?? 1,
23	    stdout: proc.stdout ? proc.stdout.toString("utf8").trim() : "",
24	    stderr: proc.stderr ? proc.stderr.toString("utf8").trim() : "",
25	  };
26	}
27	
28	/**
29	 * What to invoke for `gh`, as an argv prefix.
30	 *
31	 * `gh` everywhere except a test, which points this at its fake. It is an env var
32	 * rather than a directory on PATH because PATH does not work for this on Windows: a
33	 * bare command resolves through PATHEXT, so the fake has to carry an extension, and
34	 * the only extensions Windows will run are a compiled `.exe` or a `.cmd` — which
35	 * Bun and Node refuse to pass arguments containing `"` or `|` to, on purpose, since
36	 * cmd.exe would re-parse them. Half this repository's `gh` calls carry a jq
37	 * expression, so a `.cmd` shim rejects them.
38	 *
39	 * The fake was on PATH, and on Windows it was silently never used: what ran was the
40	 * real `gh`, with the developer's own credentials, against this repository. This
41	 * removes the resolution step that made that possible rather than fixing it, because
42	 * the failure mode of getting it wrong is writing to a live repository.
43	 *
44	 * Named for what it is. This is a test seam and nothing else: it takes a script, run by
45	 * the runtime already running, so it cannot be mistaken for configuration naming where
46	 * a real installation keeps its CLI.
47	 */
48	function ghCommand(): string[] {
49	  const fake = (process.env.ATOMATON_FAKE_GH ?? "").trim();
50	  // `process.execPath`, not `"bun"`. Resolving the name has the same problem one layer
51	  // down: a Bun installed through npm is reached by `bun.cmd`, so spawning `bun` hits
52	  // the same refusal for the same arguments. The absolute path of the runtime already
53	  // running this cannot be a shim.
54	  return fake ? [process.execPath, fake] : ["gh"];
55	}
56	
57	/** Run the `gh` CLI. Inherits GH_TOKEN from the parent environment. */
58	export function gh(...args: string[]): RunResult {
59	  return run([...ghCommand(), ...args]);
60	}
61	
62	/**
63	 * Run a READ through `gh`, treating an upstream failure as no answer rather than as
64	 * an answer of "no".
65	 *
66	 * GitHub returned `HTTP 504` for one `gh api repos/.../pulls/427` call and the run
67	 * died on it: the reviewer never started, and the pull request carried a red check
68	 * for a defect in neither the code nor the machinery. There is nothing to learn from
69	 * a 504 and nothing for an agent to do about it.
70	 *
71	 * Reads only, which is the whole reason this is a separate function rather than a
72	 * change to `gh` itself. A mutation that returns 502 may well have been applied, and
73	 * the invariants here are the kind a second attempt breaks -- one comment per run,
74	 * one dispatch per handoff. So the retry has to be asked for, by a caller that knows
75	 * its call changes nothing.
76	 *
77	 * Three attempts, widening, because the point is to outlast a blip rather than to
78	 * sit out an outage: a run holds a runner while it sleeps.
79	 */
80	export function ghRead(...args: string[]): RunResult {
81	  let result = gh(...args);
82	  for (const delay of [2_000, 6_000]) {
83	    if (result.code === 0 || !looksTransient(result)) return result;
84	    console.error(
85	      `::warning::gh ${args.slice(0, 2).join(" ")} failed transiently, retrying: ${result.stderr || result.stdout}`,
86	    );
87	    Bun.sleepSync(delay);
88	    result = gh(...args);
89	  }
90	  return result;
91	}
92	
93	/**
94	 * Whether a failure came from the far end rather than from the request.
95	 *
96	 * A 404 is an answer; a 504 is the absence of one. 429 belongs here as well: it is a
97	 * request to wait, and waiting is what a retry does.
98	 */
99	export function looksTransient(result: RunResult): boolean {
100	  const text = `${result.stderr} ${result.stdout}`;
101	  // Character classes rather than shorthand: this line has lost a backslash to
102	  // tooling twice, and `5dd` compiles just as happily as the version that works.
103	  if (/HTTP (429|5[0-9][0-9])(?![0-9])/.test(text)) return true;
104	  return /(timeout|timed out|connection reset|unexpected EOF|TLS handshake|temporary failure)/i.test(text);
105	}
106	
107	/**
108	 * Run `gh` and keep its stdout as bytes.
109	 *
110	 * `gh` above decodes stdout as UTF-8 and trims it, which is right for JSON and
111	 * ruinous for anything else: a PNG through that comes out as replacement
112	 * characters with its ends shaved off. Anything binary — an attached image, a
113	 * downloaded asset — has to come through here instead.
114	 */
115	export function ghBytes(...args: string[]): { code: number; bytes: Uint8Array } {
116	  const proc = Bun.spawnSync({ cmd: [...ghCommand(), ...args], stdout: "pipe", stderr: "pipe" });
117	  return { code: proc.exitCode ?? 1, bytes: proc.stdout ?? new Uint8Array() };
118	}
119	
120	/**
121	 * Run `gh` and parse its stdout as JSON. Throws on non-zero exit.
122	 *
123	 * `T | null`, because empty stdout produces `null` and the signature used to say
124	 * `T`. `null as T` is a cast that makes the type system agree with a claim that
125	 * is not true: the one production caller defends with `?? []`, and the next one
126	 * would have had no reason to.
127	 */
128	export function ghJson<T = unknown>(...args: string[]): T | null {
129	  const { code, stdout, stderr } = gh(...args);
130	  if (code !== 0) {
131	    throw new Error(`gh ${args.join(" ")}: ${stderr || stdout}`);
132	  }
133	  return stdout ? (JSON.parse(stdout) as T) : null;
134	}
135	
136	/** The argv both GraphQL entry points build, so the two cannot drift. */
137	function graphqlArgs(query: string, variables: Record<string, string | number>): string[] {
138	  const args = ["api", "graphql", "-f", `query=${query}`];
139	  for (const [key, value] of Object.entries(variables)) {
140	    args.push("-F", `${key}=${value}`);
141	  }
142	  return args;
143	}
144	
