export function gitRunWith(options: GitRunOptions, ...args: string[]): RunResult {
  const proc = Bun.spawnSync({
    cmd: ["git", ...args],
    stdout: "pipe",
    stderr: "pipe",
    ...(options.stdin !== undefined ? { stdin: Buffer.from(options.stdin) } : {}),
    env: { ...process.env, ...options.env },
  });
